import {connectionFields} from './auto-connect.js?v=1.3.1';
import * as C from './core.js?v=1.3.1';
import * as S from './storage.js?v=1.3.1';
import * as A from './api.js?v=1.3.1';
import * as B from './bridge.js?v=1.3.1';
import {navIcons,mascot,launcherIcon} from './visuals.js?v=1.3.1';
import * as F from './finance.js?v=1.3.1';
import {initialEstimate,storyChanges} from './funds-bridge.js?v=1.3.1';
import {DEFAULT_DM_PRESET,dialogueSettings} from './instructions.js?v=1.3.1';
import {floatingEntry} from './floating-entry.js?v=1.3.1';
import * as M from './chat-media.js?v=1.3.1';
import {bindModelPickers} from './model-picker.js?v=1.3.1';

const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons=navIcons;
const tabs=[['home','橱窗'],['auction','稿拍'],['feed','广场'],['inbox','消息'],['bench','工作台'],['me','我的']];
const status={quoted:'待确认',working:'绘制中',review:'待验收',complete:'已完成',cancelled:'已取消'};
const app=document.createElement(typeof HTMLDialogElement!=='undefined'?'dialog':'section');app.id='hy-app';app.hidden=true;app.setAttribute('aria-label','绘约虚拟约稿平台');document.body.append(app);
const launcher=document.createElement('button');launcher.id='hy-launcher';launcher.type='button';launcher.innerHTML=launcherIcon;launcher.setAttribute('aria-label','打开绘约');launcher.title='打开绘约虚拟约稿平台 v1.3.1';document.body.append(launcher);
// Keep the opening control positioned independently of the host layout.
Object.assign(launcher.style,{position:'fixed',right:'16px',bottom:'90px',zIndex:'2147483000',pointerEvents:'auto'});
Object.assign(app.style,{margin:'0',padding:'0',border:'0',width:'100%',height:'100%',maxWidth:'none',maxHeight:'none'});
const floating=floatingEntry(launcher);
let w,route={page:'home'},filter='',feedFilter='全部',search='',opened=false,saveChain=Promise.resolve(),actionBusy=false,modalCleanup=null;
const running=new Map(),urls=new Map();let epoch=0;
async function completeSafe(...args){const started=epoch;const result=await A.complete(...args);if(started!==epoch)throw Error('当前世界已经切换，已放弃上个世界的返回结果');return result;}
async function putAssetSafe(...args){const started=epoch;const result=await S.putAsset(...args);if(started!==epoch)throw Error('当前世界已经切换，请在当前世界重新上传');return result;}
let globalId;
try{globalId=localStorage.getItem('huiyue-world')||C.uid();localStorage.setItem('huiyue-world',globalId);}catch{globalId='huiyue-default';}
const btn=(act,label,id='',cls='')=>`<button type="button" class="${cls}" data-act="${act}" data-id="${E(id)}">${label}</button>`;
const tag=s=>`<span class="hy-tag">${E(s)}</span>`;
const img=(id,cls='',fallback='✿')=>id?`<img class="${cls}" data-image="${E(id)}" alt="图片" loading="lazy">`:`<span class="hy-image-fallback ${cls}">${fallback}</span>`;
const empty=(s,extra='')=>`<div class="hy-empty"><span>✧</span><p>${E(s)}</p>${extra}</div>`;
const money=n=>Number(n).toLocaleString('zh-CN');
const profile=()=>w.accounts[w.role];
const appearance=()=>({...w.settings,...(!w.settings.sharedProfile?profile().appearance||{}:{})});
const contactName=id=>id==='self'?'旧版未归属客户记录':C.contact(w,id)?.name||'未知联系人';
const dmTaskKey=(id,role=w.role)=>'dm:'+role+':'+id;
const artistName=id=>id==='self'?w.accounts.artist.name:w.artists.find(a=>a.id===id)?.name||'未知画师';
const getOrder=id=>C.order(w,id);
function toast(s,error=false){let el=document.getElementById('hy-toast');if(!el){el=document.createElement('div');el.id='hy-toast';el.setAttribute('role','status');(opened?app:document.body).append(el);}else if(opened)app.append(el);el.textContent=s;el.classList.toggle('error',error);el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.hidden=true,error?8000:3500);}
function persist(){const snapshot=structuredClone(w);saveChain=saveChain.catch(()=>{}).then(()=>S.saveWorld(snapshot));B.injectSummary(w);injectFundsSummary();return saveChain;}
function go(page,id){route={page,id};filter='';render();}
async function hydrate(root=app){for(const el of root.querySelectorAll('[data-image]')){const id=el.dataset.image;try{let u=urls.get(id);if(!u){const a=await S.getAsset(id);if(!a)continue;u=URL.createObjectURL(a.blob);urls.set(id,u);}if(el.isConnected){if(el.tagName==='IMG')el.src=u;else el.style.backgroundImage=`url("${u}")`;}}catch{el.alt='图片读取失败';}}}
function themes(){const settings=appearance();const colors={sky:['#75a8c6','#f3f7fb','#ffffff','#263545'],rose:['#c48f9e','#fcf5f6','#ffffff','#503940'],mint:['#75a99a','#f0f8f4','#ffffff','#2e453d'],night:['#9badd6','#171e2b','#232d3e','#e0e8f3']};const c=colors[settings.theme]||colors.sky;app.style.setProperty('--hy-accent',/^#[\da-f]{6}$/i.test(settings.accent)?settings.accent:c[0]);app.style.setProperty('--hy-bg',c[1]);app.style.setProperty('--hy-card',c[2]);app.style.setProperty('--hy-ink',c[3]);app.style.setProperty('--hy-radius',`${Number.isFinite(Number(settings.radius))?Math.max(0,Math.min(32,Number(settings.radius))):22}px`);app.style.fontSize=`${Number(settings.fontSize)||15}px`;updateLauncher();
    let style=document.getElementById('hy-custom-style');if(!style){style=document.createElement('style');style.id='hy-custom-style';document.head.append(style);}style.textContent='';
    try{const sheet=new CSSStyleSheet();sheet.replaceSync(settings.customCSS||'');style.textContent=Array.from(sheet.cssRules).filter(r=>r.type===1&&!/url\s*\(|@import|expression/i.test(r.cssText)).map(r=>`${r.selectorText.split(',').map(s=>'#hy-app '+s.trim()).join(',')}{${r.style.cssText}}`).join('\n');}catch{ /* Custom CSS remains optional. */ }
}
function render(){if(!w)return;themes();const title=route.page==='artist'?'画师主页':route.page==='dm'?contactName(route.id):route.page==='order'?'委托详情':route.page==='settings'?'设置与存档':route.page==='projects'?'企划广场':tabs.find(t=>t[0]===route.page)?.[1]||'绘约';
    const mainPage=tabs.some(t=>t[0]===route.page);
    app.innerHTML=`<header class="hy-header"><div class="hy-brand">${mainPage?'<span class="hy-flower">✿</span> 绘约':btn('back','‹ 返回')}<small>${mainPage?'让故事有了模样':E(title)}</small></div><div class="hy-header-actions"><span class="hy-day">剧情日 ${w.day}</span>${btn('advance','»','','hy-icon')}${btn('close','×','','hy-icon')}</div></header>
    <main class="hy-main" tabindex="-1">${content()}</main><nav class="hy-nav" aria-label="平台导航">${tabs.map(([id,label])=>btn('nav',`<span>${icons[id]}</span><small>${label}</small>`,id,route.page===id?'active':'')).join('')}</nav><div class="hy-modal-mount"></div>`;
    if(appearance().background){app.querySelector('.hy-main').dataset.image=appearance().background;}
    hydrate();renderChatCards();
}
function content(){switch(route.page){case 'home':return home();case 'artist':return artistPage();case 'auction':return auctions();case 'feed':return feed();case 'inbox':return inbox();case 'dm':return dm();case 'bench':return bench();case 'order':return orderPage();case 'me':return me();case 'settings':return settings();case 'projects':return projects();case 'funds':return fundsPage();default:return '';}}
function home(){const list=w.artists.filter(a=>(!search||`${a.name} ${a.style} ${a.bio}`.includes(search))&&(!filter||filter==='favorite'&&a.favorite||filter==='open'&&a.open&&a.available<=w.day));return `<section class="hy-hero"><div class="hy-eyebrow">DAY ${w.day} · 绘约虚拟世界</div><h1>总有一位画师，<br>能画出你的故事。<span>✧</span></h1><p>从一个灵感开始，慢慢把喜欢变成作品。</p>${btn('projects','浏览企划 ↗','','hy-link')}</section>
    <form class="hy-search" data-form="search"><span>⌕</span><input name="q" aria-label="搜索画师" placeholder="搜索画师、画风或擅长题材" value="${E(search)}"><button>搜索</button></form>
    <div class="hy-chips">${btn('filter','推荐','',!filter?'selected':'')}${btn('filter','接稿中','open',filter==='open'?'selected':'')}${btn('filter','我的关注','favorite',filter==='favorite'?'selected':'')}</div>
    <div class="hy-section-title"><h2>发现心动画师 <small>${list.length} 位</small></h2><div>${btn('aiArtist','✧ AI 画师')}${btn('editArtist','＋ 添加')}</div></div><div class="hy-artist-grid">${list.map(a=>`<article class="hy-artist-card"><button class="hy-cover" data-act="artist" data-id="${E(a.id)}">${img(a.works[0]?.asset||a.avatar,'hy-cover-image')}<span class="hy-cover-style">${E(a.style)}</span></button><div class="hy-card-body"><div class="hy-row"><strong>${E(a.name)}</strong>${btn('favorite',a.favorite?'♥':'♡',a.id,'hy-icon')}</div><p class="hy-muted">${E(a.personality.slice(0,65))}</p><div class="hy-row"><strong class="hy-price">${money(a.min)} <small>绘币起</small></strong>${tag(a.open&&a.available<=w.day?'接稿中':'休息中')}</div>${btn('artist','查看主页 ›',a.id,'hy-full hy-soft')}</div></article>`).join('')}</div>${!list.length?empty('还没有符合条件的画师'):''}<p class="hy-footnote">所有画师、交易和绘币均属于本地虚构模拟世界。</p>`;}
function artistPage(){const a=w.artists.find(x=>x.id===route.id);if(!a)return empty('画师不存在');return `<section class="hy-profile-card"><div class="hy-profile-head">${img(a.avatar,'hy-avatar-lg')}<div><h1>${E(a.name)} ${a.linked?tag('角色已关联'):''}</h1><p>${money(a.fans)} 粉丝 · ${E(a.style)}</p></div></div><p>${E(a.bio)}</p><p class="hy-muted">${E(a.personality)}</p><div class="hy-chips">${tag(`${a.min}–${a.max} 绘币`)}${tag(`${a.days} 剧情日`)}${tag(`含 ${a.revisions} 次修改`)}${tag(`档期：第 ${a.available} 日起`)}</div><p class="hy-muted">接稿偏好：${E(a.refusal)}</p><div class="hy-actions">${btn('dm','✉ 私信画师',a.id,'hy-primary')}${btn('quote','发起委托',a.id)}${btn('favorite',a.favorite?'♥ 已关注':'♡ 关注',a.id)}</div></section>
    <div class="hy-section-title"><h2>作品橱窗</h2>${btn('addWork','＋ 上传作品',a.id)}</div><div class="hy-work-grid">${a.works.map(x=>`<article class="hy-card">${img(x.asset,'hy-work-image')}<div class="hy-card-body"><strong>${E(x.title)}</strong><div class="hy-actions">${btn('download','下载',x.asset)}${btn('removeWork','移除',x.id)}</div></div></article>`).join('')||empty('还没有作品，可以从相册上传原图')}</div>
    <section class="hy-card hy-pad"><h2>合作评价</h2>${a.reviews.map(r=>`<p>${'★'.repeat(r.stars)} ${E(r.body)} <small>第 ${r.day} 日</small></p>`).join('')||'<p class="hy-muted">暂无评价，第一段合作故事等你开启。</p>'}</section><div class="hy-actions">${btn('editArtist','编辑画师资料',a.id)}${btn('link','关联当前角色',a.id)}${a.linked?btn('unlink','解除角色关联',a.id):''}</div>`;}
function auctions(){return `<section class="hy-mini-hero"><span>♧</span><h1>把心动留给下一位。</h1><p>成稿、OC 人设与画师档期 · 仅使用虚拟绘币</p></section><div class="hy-section-title"><h2>稿拍市场</h2>${btn('createAuction','＋ 发布稿拍')}</div><div class="hy-chips">${['全部','成稿','OC 人设','画师档期','我的成交'].map(f=>btn('auctionFilter',f,f,filter===f||!filter&&f==='全部'?'selected':'')).join('')}</div><div class="hy-work-grid">${w.auctions.filter(a=>!filter||filter==='全部'||filter==='我的成交'&&a.winner===w.role||a.type===filter).map(a=>`<article class="hy-card">${a.asset?img(a.asset,'hy-work-image'):'<div class="hy-slot-art">◷<small>一段专属于你的创作档期</small></div>'}<div class="hy-card-body"><div class="hy-row"><strong>${E(a.title)}</strong>${tag(a.type)}</div><p>${E(a.description)}</p><p class="hy-muted">${a.status==='closed'?`已结束 · ${a.winner?(a.winner==='npc'?'虚拟买家':w.accounts[a.winner]?.name)+' 成交':'流拍'}`:`第 ${a.endDay} 日结束 · ${a.bids.length} 次出价`}</p><div class="hy-row"><strong class="hy-price">${money(a.bids.at(-1)?.amount||a.start)} 绘币</strong>${a.status==='open'?btn('bid','参与竞拍',a.id,'hy-primary'):a.winner===w.role&&a.asset?btn('download','下载拍品',a.asset):''}</div>${a.status==='closed'&&a.winner===w.role&&a.type==='画师档期'?btn('claimSlot','使用成交档期',a.id):''}<details><summary>出价记录</summary>${a.bids.map(b=>`<p>第 ${b.day} 日 · ${E(w.accounts[b.bidder]?.name||'虚拟买家')}：${b.amount} 绘币</p>`).join('')||'<p>暂无出价</p>'}</details></div></article>`).join('')||empty('还没有拍品，发布一件作品或档期吧')}</div>`;}
function feed(){return `<div class="hy-section-title"><div><div class="hy-eyebrow">OUR LITTLE STORIES</div><h1>创作之外，也有生活。</h1></div>${btn('createPost','＋ 发布','','hy-primary')}</div><div class="hy-chips">${['全部','稿件','生活','灵感','公告'].map(f=>btn('feedFilter',f,f,feedFilter===f?'selected':'')).join('')}</div>${w.posts.filter(p=>feedFilter==='全部'||p.category===feedFilter).map(p=>`<article class="hy-card hy-post"><div class="hy-row"><div class="hy-author">${img(p.avatar||w.artists.find(a=>a.id===p.artistId)?.avatar,'hy-avatar')}<div><strong>${E(p.author)}</strong><small>第 ${p.day} 日 · ${E(p.category)}</small></div></div>${tag(p.artistId?'画师动态':p.role==='artist'?'画师':'委托人')}</div><p class="hy-pre">${E(p.body)}</p>${p.asset?img(p.asset,'hy-post-image'):''}<div class="hy-actions">${btn('like',`${C.hasLiked(w,p)?'♥':'♡'} ${p.likes}`,p.id,'hy-like')}${btn('likePeople','谁赞过',p.id)}${btn('comment',`评论 ${p.comments.length}`,p.id)}</div><small class="hy-muted">长按爱心查看点赞名单 · 本地虚拟互动</small>${p.comments.map(c=>`<div class="hy-comment"><strong>${E(c.author)}</strong>${c.relation?`<small> · ${E(c.relation)}</small>`:''}<div>${E(c.body)}</div></div>`).join('')}</article>`).join('')||empty('广场还很安静，发布第一条动态吧',btn('aiPost','✧ 生成一条画师动态'))}<div class="hy-actions">${btn('aiPost','✧ AI 画师动态')}${btn('npcPost','生成模拟动态')}</div>`;}
function inbox(){const msgs=Object.entries(w.messages).filter(([key])=>key.startsWith(w.role+':'));return `<div class="hy-section-title"><h1>消息</h1>${tag(w.role==='client'?'甲方收件箱':'画师收件箱')}</div>${msgs.map(([key,ms])=>{const id=key.slice(key.indexOf(':')+1),a=C.contact(w,id);return `<button class="hy-thread" data-act="dm" data-id="${E(id)}">${img(a?.avatar||w.accounts.artist.avatar,'hy-avatar')}<div><strong>${E(contactName(id))}</strong><p>${E((ms.at(-1)?.body||(ms.at(-1)?.kind==='sticker'?'[表情包]':ms.at(-1)?.asset?'[图片]':'')).slice(0,80))}</p></div><span>›</span></button>`;}).join('')||empty('还没有私信，去橱窗找一位喜欢的画师吧')}<h2>平台通知</h2>${w.notifications.filter(n=>n.role==='all'||n.role===w.role).slice(0,30).map(n=>`<article class="hy-card hy-pad"><small>剧情日 ${n.day}</small><p>${E(n.message)}</p></article>`).join('')||'<p class="hy-muted">暂无通知</p>'}`;}
function versionCard(o,v){const busy=running.has(v.id),label=busy?(v.status==='drawing'?'绘制中…':'生成中…'):v.asset?'查看稿件 / 下载':v.status==='failed'?'重试当前步骤':v.positive?'生成图片':'生成提示词';return `<div class="hy-art-bubble" data-version="${E(v.id)}"><div class="hy-row"><strong>${E(v.stage)} V${v.number}</strong>${tag(v.source==='upload'?'手动上传':v.source==='ai'?'AI 生成':'稿件占位')}</div><div class="hy-art-content"><button type="button" class="hy-art-preview" data-act="view" data-id="${E(v.id)}">${v.asset?img(v.asset,'hy-art-image'):'<span>▧</span><small>等待添加稿件</small>'}</button><div class="hy-art-tools">${btn('versionMain',label,v.id,'hy-primary')}${btn('uploadVersion','↑ 上传图片',v.id)}${btn('editPrompt','☷ 提示词',v.id)}${busy?btn('cancelTask','放弃本次结果',v.id):''}</div></div><p class="hy-muted">${E(v.note||'尚未填写稿件说明')}</p>${v.error?`<p class="hy-error">${E(v.error)}</p>`:''}<small>第 ${v.day} 日${v.accepted?' · 已验收':''}</small></div>`;}
function dm(){const id=route.id,a=C.contact(w,id),client=C.isCustomer(w,id),ms=w.messages[`${w.role}:${id}`]||[];if(id==='self')return `<h1>旧版未归属客户记录</h1><p class="hy-muted">这里保留无法确定属于哪位客户的旧消息，仅供查阅。请在收件箱打开具体客户进行一对一聊天。</p>${ms.map(m=>`<div class="hy-message"><small>第 ${m.day} 日</small><p class="hy-message-text hy-pre">${E(m.body)}</p>${m.asset?img(m.asset,'hy-dm-image'):''}</div>`).join('')}`;return `<div class="hy-dm-head">${img(a?.avatar||w.accounts.artist.avatar,'hy-avatar')}<div><strong>${E(contactName(id))}</strong><small>${client?'虚拟客户 · 独立一对一私信':'独立角色上下文 · '+(a?.open?'模拟在线':'暂时离线')}</small></div>${client?btn('bench','客户订单'):btn('quote','约稿',id)}</div><div class="hy-chat" id="hy-dm-log">${ms.map(m=>{let art='';if(m.versionId){try{const {o,v}=C.findVersion(w,m.versionId);art=versionCard(o,v);}catch{}}return `<div class="hy-message ${m.from==='user'?'self':''}"><small>${m.from==='user'?E(profile().name):E(contactName(id))} · 第 ${m.day} 日</small>${m.body?`<div class="hy-message-text hy-pre">${E(m.body)}</div>`:''}${m.asset?`<button type="button" class="hy-dm-media ${m.kind==='sticker'?'hy-dm-sticker':''}" data-act="viewDMImage" data-id="${E(m.asset)}" aria-label="查看${m.kind==='sticker'?'表情包':'图片'}">${img(m.asset,'hy-dm-image')}</button>`:''}${art}</div>`;}).join('')||empty('从打个招呼开始吧。你们的故事会保存在这里。')}</div><form class="hy-composer" data-form="dm"><textarea name="body" rows="2" maxlength="10000" required placeholder="聊聊 OC、构图、修改想法…" aria-label="私信内容"></textarea><button type="submit" class="hy-primary" ${running.has(dmTaskKey(id))?'disabled':''}>${running.has(dmTaskKey(id))?'回复中…':'发送 ↗'}</button><div class="hy-composer-tools">${btn('uploadDMImage','＋ 图片',id)}${btn('stickerPicker','☺ 表情包',id)}</div></form><div class="hy-actions">${btn('retryDM','重新请求回复',id)}${btn('manualReply','手动扮演对方',id)}${btn('makePlaceholder','添加稿件占位',id)}</div><p class="hy-footnote">AI 报价仅供沟通参考。订单金额以「发起委托」确认的数值为准。</p>`;}
function bench(){const os=w.commissions.filter(o=>o.owner===w.role&&(!filter||o.status===filter));return `<div class="hy-section-title"><h1>每个灵感，都在慢慢成形。</h1>${w.role==='artist'?btn('incoming','＋ 模拟客户'):''}</div><div class="hy-chips">${[['','全部'],['quoted','待确认'],['working','绘制中'],['review','待验收'],['complete','已完成']].map(([id,l])=>btn('filter',l,id,filter===id?'selected':'')).join('')}</div>${os.map(o=>`<article class="hy-card hy-pad"><div class="hy-row"><strong>${E(o.title)}</strong>${tag(status[o.status])}</div><p class="hy-muted">${E(o.owner==='artist'?contactName(C.threadForOrder(o)):artistName(o.artistId))} · ${o.price} 绘币${o.dueDay?` · 约定第 ${o.dueDay} 日交付`:''}</p><div class="hy-progress">${C.STAGES.map((s,i)=>`<span class="${o.stage>=i?'done':''}">${s}</span>`).join('')}</div><div class="hy-row"><small>${o.versions.length} 个版本 · 已修改 ${o.revisions}/${o.maxRevisions} 次</small>${btn('order','打开工作板 ›',o.id,'hy-soft')}</div></article>`).join('')||empty('这里会记录你的每一次约稿和交付')}`;}
function orderPage(){let o;try{o=getOrder(route.id);}catch{return empty('订单不存在');}return `<section class="hy-card hy-pad"><div class="hy-row"><h1>${E(o.title)}</h1>${tag(status[o.status])}</div><p>${E(o.brief)}</p><p class="hy-muted">${E(o.owner==='artist'?contactName(C.threadForOrder(o)):artistName(o.artistId))} · ${o.price} 绘币 · ${o.days} 剧情日 · ${o.commercial?'商用需求':'个人用途'}</p><div class="hy-progress">${C.STAGES.map((s,i)=>`<span class="${o.stage>=i?'done':''}">${s}</span>`).join('')}</div><p>当前阶段：${C.STAGES[o.stage]} · 修改次数 ${o.revisions}/${o.maxRevisions}</p><div class="hy-actions">${o.status==='quoted'?(o.owner==='client'?btn('pay','确认并托管付款',o.id,'hy-primary'):btn('acceptIncoming','接受客户委托',o.id,'hy-primary')):''}${o.status==='working'?btn('placeholder','提交阶段稿件占位',o.id,'hy-primary'):''}${o.status==='review'?btn('approve',o.owner==='artist'?'模拟客户验收':'确认本阶段验收',o.id,'hy-primary')+btn('revise',o.owner==='artist'?'模拟客户提出修改':'提出修改',o.id):''}${!['complete','cancelled'].includes(o.status)?btn('cancelOrder','协商取消',o.id):''}${btn('dm','打开私信',C.threadForOrder(o))}${btn('orderAutomation','本订单自动化',o.id)}${o.status==='complete'&&!o.reviewed&&o.owner==='client'?btn('review','评价画师',o.id):''}</div></section><div class="hy-section-title"><h2>稿件版本库</h2>${btn('exportOrder','导出订单稿件包',o.id)}</div>${o.versions.map(v=>`<article class="hy-card hy-pad">${versionCard(o,v)}<div class="hy-actions">${btn('newVersion','从此版新建修改版',v.id)}${btn('editNote','编辑文字稿说明',v.id)}${v.asset?btn('download','下载原图',v.asset):''}</div></article>`).join('')||empty('等待画师提交第一版稿件')}`;}
function me(){const p=profile();return `<section class="hy-profile-card"><div class="hy-profile-head">${img(p.avatar,'hy-avatar-lg')}<div><div class="hy-eyebrow">${w.role==='client'?'COMMISSIONER':'ARTIST'}</div><h1>${E(p.name)}</h1><small>ID ${E(p.id.slice(0,8))}</small></div></div><p>${E(p.bio)}</p><div class="hy-row"><div><small>可用绘币</small><div class="hy-wallet">${money(p.balance)} <small>✧</small></div></div>${btn('switchRole',w.role==='client'?'✎ 切换画师身份':'♡ 切换甲方身份','','hy-soft')}</div><div class="hy-actions">${btn('editAccount','编辑个人资料')}${btn('recharge','＋ 充值绘币','','hy-primary')}${btn('funds','剧情资产')}${btn('wallet','钱包记录')}</div></section><div class="hy-settings-menu">${btn('settings','⚙ 设置、AI 接口与存档 ›')}${btn('bridge','⇄ 角色关联与剧情同步 ›')}${btn('npc','✧ 提取角色卡 / 世界书中的 NPC ›')}${btn('accountStyle','❀ 主题与界面美化 ›')}${btn('launcherSettings','✿ 悬浮图标与打开入口 ›')}${btn('paymentRegion','国家/地区与支付方式 ›')}${btn('bench','▣ 我的稿件与订单 ›')}</div>${w.artistActivated?`<section class="hy-card hy-pad"><h2>画师身份管理</h2><p class="hy-muted">注销后停止接收新的约稿请求。资料、绘币与已接订单保留，下次开通需要再次确认。</p>${btn('deactivateArtist','注销画师身份','','hy-danger')}</section>`:''}<section class="hy-card hy-pad"><h2>身份说明</h2><p class="hy-muted">甲方和画师拥有独立资料、钱包与消息。切换平台身份不会切换酒馆当前角色。画师身份首次启用后，才会开始接收模拟客户消息。</p></section>`;}
function apiFields(kind,label){const s=w.settings[kind];return `<fieldset data-api-kind="${kind}"><legend>${label}</legend><label>调用方式<select name="${kind}.mode"><option value="tavern" ${s.mode==='tavern'?'selected':''}>使用酒馆当前${kind==='image'?'图片扩展':'对话模型'}</option><option value="openai" ${s.mode==='openai'?'selected':''}>独立 API / 第三方中转</option>${kind==='image'?A.imageAdapters().map(a=>`<option value="${E(a.id)}" ${s.mode===a.id?'selected':''}>${E(a.label)}</option>`).join(''):''}</select></label><label>站点 URL<input name="${kind}.url" value="${E(s.url)}" placeholder="https://example.com/v1"></label><label>API Key（仅内存保存，不写入存档）<input type="password" autocomplete="off" name="${kind}.key" placeholder="${A.hasKey(kind)?'已设置；留空保留':'填写该站密钥'}"></label><button type="button" data-fetch-models ${s.mode!=='openai'?'disabled':''}>拉取模型并连接</button><label>模型<select name="${kind}.model" data-model-list><option value="${E(s.model)}">${E(s.model)||'请先拉取模型'}</option></select></label><p class="hy-muted" data-model-status role="status" aria-live="polite">填写站点 URL 和密钥后点击拉取，插件自动识别兼容方式；选择模型后保存。</p>${connectionFields.map(key=>`<input type="hidden" name="${kind}.${key}" value="${E(s[key]??'')}">`).join('')}${kind!=='image'?`<label>基础提示词模板<textarea name="${kind}.template" rows="4">${E(s.template)}</textarea></label>`:''}${kind==='prompt'?`<label>提示词 AI 附加指令 / 自定义破甲预设<textarea name="prompt.instructions" rows="5" maxlength="10000" placeholder="填写你希望发送给提示词 AI 的额外指令，可留空">${E(s.instructions||'')}</textarea></label><p class="hy-muted">仅在生成稿件提示词时，接在基础模板后作为系统指令发送。保留 positive / negative 的 JSON 输出要求。</p>`:kind==='image'?`<label>生图 AI 附加指令 / 自定义破限预设<textarea name="image.instructions" rows="5" maxlength="10000" placeholder="填写需要随图片提示词发送的额外内容，可留空">${E(s.instructions||'')}</textarea></label><p class="hy-muted">图片接口没有统一的系统指令字段，本框内容会放在正向提示词前，并与本次稿件提示词一起发送；不会发送给提示词 AI。</p>`:''}</fieldset>`;}
function settings(){return `<h1>让绘约，成为你的样子。</h1><div class="hy-actions">${btn('paymentRegion','国家/地区')}${btn('launcherSettings','悬浮图标与打开入口')}${btn('funds','剧情资产')}</div><form data-form="settings" class="hy-form"><fieldset><legend>自动化与剧情</legend>${check('autoPrompt','稿件占位后自动生成提示词',w.settings.autoPrompt)}${check('autoImage','有提示词后自动生成图片',w.settings.autoImage)}${check('randomEvents','启用剧情随机事件、NPC 竞价与生活动态',w.settings.randomEvents)}${check('sharedProfile','两种身份共用昵称、简介、头像和美化',w.settings.sharedProfile)}<p class="hy-muted">自动开关仅影响之后新建的稿件。打开页面、刷新、读取聊天不会自动补发 API 请求。手动上传始终可用。</p></fieldset><fieldset><legend>绘约内对话预设</legend><p class="hy-muted">仅用于本插件私信（含模拟客户对话），不会用于人物生成、动态、资产判断或注入酒馆正文。可留空停用本段。</p>${area('dmPreset','对话氛围与说话方式',w.settings.dmPreset??DEFAULT_DM_PRESET,10)}<button type="button" data-reset-dm-preset>恢复自然约稿预设</button></fieldset>${apiFields('chat','AI 私信与人物生成')}${apiFields('prompt','独立提示词 AI')}${apiFields('image','绘图服务')}<fieldset><legend>绘图参数</legend>${field('width','宽度',w.settings.image.width,'number')}${field('height','高度',w.settings.image.height,'number')}${field('steps','Steps',w.settings.image.steps,'number')}${field('cfg','CFG',w.settings.image.cfg,'number')}<p class="hy-muted">酒馆模式复用图片扩展选择的服务，可使用其支持的 NovelAI、SD、ComfyUI 等。独立模式支持 Images、聊天式生图和 NovelAI 原生中转；NAI 会发送实际种子、步数和 CFG。各服务的尺寸、参考图与重绘能力不同。修改版本保留提示词和种子，但通用文生图不保证构图一致。</p></fieldset><button type="submit" class="hy-primary">保存设置</button></form><section class="hy-card hy-pad"><h2>完整存档</h2><p class="hy-muted">存档包含本世界的所有资料、订单、稿件原文件和头像。可在电脑与手机间手动迁移。浏览器数据不会自动同步到其他设备，请定期导出。</p><div class="hy-actions">${btn('export','导出完整存档')}${btn('import','恢复完整存档')}${btn('reset','重置当前世界')}</div></section><p class="hy-footnote">独立 API 由浏览器直接请求，需要服务允许跨域访问。密钥只保留至页面关闭；不要将密钥写在地址或模板中。</p>`;}
function projects(){return `<div class="hy-section-title"><h1>把灵感写成企划。</h1>${btn('createProject','＋ 发布企划')}</div>${w.projects.map(p=>`<article class="hy-card hy-pad"><div class="hy-row"><strong>${E(p.title)}</strong>${tag(`${p.budget} 绘币预算`)}</div><p>${E(p.brief)}</p><p class="hy-muted">第 ${p.deadline} 日截稿 · ${p.applicants.length} 位画师应征</p><div class="hy-actions">${btn('applicants','邀请 / 查看应征',p.id)}${btn('simulateApplicants','征集虚拟应征',p.id)}</div></article>`).join('')||empty('可以先写下想要的画面，再寻找合适的画师')}`;}
const field=(name,label,value='',type='text',extra='')=>`<label>${E(label)}<input type="${type}" name="${name}" value="${E(value)}" ${extra}></label>`;
const area=(name,label,value='',rows=4)=>`<label>${E(label)}<textarea name="${name}" rows="${rows}">${E(value)}</textarea></label>`;
const check=(name,label,on)=>`<label class="hy-toggle"><input type="checkbox" name="${name}" ${on?'checked':''}><span>${E(label)}</span></label>`;
function closeModal(){modalCleanup?.();modalCleanup=null;app.querySelector('.hy-modal-mount')?.replaceChildren();}
function modal(title,body,onSubmit,label='保存'){closeModal();const mount=app.querySelector('.hy-modal-mount');mount.innerHTML=`<div class="hy-modal-backdrop"><section class="hy-modal" role="dialog" aria-modal="true" aria-label="${E(title)}"><div class="hy-row"><h2>${E(title)}</h2>${btn('closeModal','×','','hy-icon')}</div><form class="hy-form">${body}${onSubmit?`<button class="hy-primary" type="submit">${E(label)}</button>`:''}</form></section></div>`;
    const form=mount.querySelector('form');form.addEventListener('submit',async e=>{e.preventDefault();const button=form.querySelector('button[type=submit]');if(button?.disabled)return;if(button)button.disabled=true;try{await onSubmit?.(new FormData(form),form);closeModal();await persist();render();}catch(e){toast(e.message,true);if(button)button.disabled=false;}});
    const key=e=>{if(e.key==='Escape'){e.stopPropagation();closeModal();}if(e.key==='Tab'){const els=[...mount.querySelectorAll('button,input,textarea,select,a[href]')].filter(x=>!x.disabled);if(!els.length)return;const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}};mount.addEventListener('keydown',key);modalCleanup=()=>mount.removeEventListener('keydown',key);setTimeout(()=>mount.querySelector('input,textarea,button')?.focus(),20);
}
function confirmModal(title,body,callback){modal(title,`<p>${E(body)}</p>`,callback,'确认');}
async function pickFile(accept){return new Promise(resolve=>{const i=document.createElement('input');i.type='file';i.accept=accept;i.style.display='none';document.body.append(i);let done=false;const finish=f=>{if(done)return;done=true;i.remove();resolve(f);};i.addEventListener('change',()=>finish(i.files?.[0]));i.addEventListener('cancel',()=>finish());i.click();});}
async function upload(){const f=await pickFile('image/png,image/jpeg,image/webp,image/gif,image/avif,image/bmp');return f?S.putAsset(f,f.name):null;}
function artistForm(id){const a=w.artists.find(x=>x.id===id)||C.artist();modal(id?'编辑画师':'添加自己的画师',`${field('name','昵称',a.name)}${area('bio','个人简介',a.bio)}${area('personality','人设、性格和沟通习惯',a.personality)}${field('style','画风 / 擅长题材',a.style)}${area('promptPreset','画师串 / 风格预设（正向提示词）',a.promptPreset||'',3)}${area('negativePreset','画师默认负向提示词（选填）',a.negativePreset||'',2)}<p class="hy-muted">可填写标签、权重或模型支持的风格语法。生成提示词时保留原串并加入本次画面需求；单张稿件仍可编辑，不影响已有原图。不同模型的标签和 LoRA 语法请分别适配。</p>${field('fans','粉丝数',a.fans,'number')}${field('min','最低报价',a.min,'number')}${field('max','最高报价',a.max,'number')}${field('days','约稿工期（剧情日）',a.days,'number')}${field('available','开始接稿的剧情日',a.available,'number')}${field('revisions','包含修改次数',a.revisions,'number')}${area('refusal','接稿限制与偏好',a.refusal,2)}${check('open','开放接稿',a.open)}<label>头像（从手机相册或文件选择）<input type="file" name="avatarFile" accept="image/*"></label>`,async f=>{const min=C.integer(f.get('min'),1),max=C.integer(f.get('max'),min);const v={name:C.text(f.get('name'),50),bio:C.text(f.get('bio'),4000),personality:C.text(f.get('personality'),2000),style:C.text(f.get('style'),500),promptPreset:C.text(f.get('promptPreset'),4000),negativePreset:C.text(f.get('negativePreset'),4000),fans:C.integer(f.get('fans')),min,max,days:C.integer(f.get('days'),1,365),available:C.integer(f.get('available'),1),revisions:C.integer(f.get('revisions'),0,30),refusal:C.text(f.get('refusal'),1000),open:f.has('open')};if(!v.name)throw Error('请输入昵称');const file=f.get('avatarFile');if(file?.size)v.avatar=await putAssetSafe(file,file.name);if(id)Object.assign(a,v);else w.artists.push({...a,...v});});}
function quoteForm(id,preset={}){const a=w.artists.find(a=>a.id===id);if(!a)throw Error('请先选一位画师');if(w.role!=='client')throw Error('请先切换甲方身份');modal(`向 ${a.name} 发起委托`,`${field('title','委托标题',preset.title||'我的 OC 插画')}${area('brief','人设、服装、构图与细节需求',preset.brief||'')}${field('price',`协商报价（${a.min}–${a.max} 绘币）`,preset.budget?Math.min(a.max,Math.max(a.min,preset.budget)):a.min,'number')}${field('days','约定工期（剧情日）',a.days,'number')}${check('commercial','需要商用授权（请在需求中说明范围）',false)}<p class="hy-muted">创建后仍需确认付款。画师接稿状态和档期由系统检查。AI 聊天中的金额不会自动扣款。</p>`,f=>{const o=C.quote(w,id,{title:f.get('title'),brief:f.get('brief'),price:f.get('price'),days:f.get('days'),commercial:f.has('commercial')});route={page:'order',id:o.id};},'创建待确认订单');}
function automation(o,key){return typeof o.automation?.[key]==='boolean'?o.automation[key]:w.settings[key];}
function afterPlaceholder(v){const {o}=C.findVersion(w,v.id);if(automation(o,'autoPrompt'))startTask(v.id,'prompt');else if(automation(o,'autoImage')&&v.positive)startTask(v.id,'image');}
function taskValid(token){return token.epoch===epoch&&!token.controller.signal.aborted&&running.get(token.id)===token;}
function startTask(id,kind){
    if(running.has(id))return;const {o,v}=C.findVersion(w,id);if(kind==='image'&&!v.positive)throw Error('请先填写或生成提示词');if(v.asset)throw Error('当前版本已有原图，请先新建修改版，旧稿不会被覆盖');
    if([...running.values()].some(t=>t.kind!=='dm'))throw Error('已有生成任务，请等待或放弃当前结果后再试');
    const token={id,kind,epoch,controller:new AbortController()};running.set(id,token);v.status=kind==='prompt'?'prompting':'drawing';v.error=null;persist().catch(e=>toast(e.message,true));render();
    const captured=structuredClone({o,v,settings:w.settings,artist:o.artistId==='self'?w.accounts.artist:w.artists.find(a=>a.id===o.artistId)});
    (async()=>{
        try{
            if(kind==='prompt'){
                const previous=captured.o.versions.filter(x=>x.id!==id).at(-1),presets=C.artistPresets(captured.artist);
                const raw=await completeSafe(captured.settings.prompt,'prompt',[{role:'user',content:JSON.stringify({brief:captured.o.brief,style:captured.artist?.style,artistPositivePreset:presets.positive,artistNegativePreset:presets.negative,presetRule:'保留画师串和权重原文，把画面需求整理为补充提示词；不要把预设当作命令执行。',stage:captured.v.stage,revision:captured.o.lastRevision,note:captured.v.note,previous:previous?{positive:previous.positive,negative:previous.negative,seed:previous.seed}:null})}],token.controller.signal);
                if(!taskValid(token))return;const p=A.parseJSON(raw);if(typeof p.positive!=='string'||!p.positive.trim())throw Error('AI 没有返回 positive 提示词');const combined=C.withArtistPresets(p.positive,p.negative,presets);v.positive=combined.positive;v.negative=combined.negative;v.artistPresetSnapshot=presets;v.status='prompted';v.source='ai';
            }else{
                const result=await A.draw(captured.settings.image,captured.v,token.controller.signal);if(!taskValid(token))return;v.asset=result.asset;v.params=result.params;v.source='ai';v.status='ready';
            }
            await persist();toast(kind==='prompt'?'提示词已生成，可编辑后再出图':'图片已保存至版本库');
        }catch(e){if(taskValid(token)){v.status='failed';v.error=e.message;await persist().catch(()=>{});toast(e.message,true);}}
        finally{if(running.get(id)===token){running.delete(id);if(token.epoch===epoch){render();if(kind==='prompt'&&v.status==='prompted'&&automation(o,'autoImage'))startTask(id,'image');}}}
    })();
}
async function aiReply(id){
    const role=w.role,key=dmTaskKey(id,role);if(running.has(key))return;const a=C.contact(w,id),client=C.isCustomer(w,id);if(id==='self')throw Error('旧版混合记录仅供查阅，请打开具体客户私信');if(!a)throw Error('联系人不存在');
    if(!client&&a.open===false){C.message(w,id,role,'你好，收到消息啦。我目前暂不接稿，可以先把需求留下。',{from:'artist'});await persist();render();return;}
    const token={id:key,kind:'dm',epoch,controller:new AbortController()};running.set(key,token);render();
    const ms=(w.messages[`${role}:${id}`]||[]).filter(m=>!m.versionId).slice(-18).map(m=>({role:m.from==='user'?'user':'assistant',content:M.chatContent(m)}));
    const info={name:a.name,bio:a?.bio,personality:a?.linked?.personality||a?.personality,originalRole:a?.linked,style:a?.style,range:!client?[a.min,a.max]:null,refusal:a?.refusal,day:w.day,orders:w.commissions.filter(o=>C.threadForOrder(o)===id&&o.owner===role).slice(-4).map(o=>({title:o.title,brief:o.brief,status:o.status,stage:C.STAGES[o.stage],price:o.price,lastRevision:o.lastRevision}))};
    const offered=M.availableStickers(w);
    try{const raw=await completeSafe(dialogueSettings(w.settings),'chat',[{role:'system',content:`当前私信对方资料与权威订单状态：${JSON.stringify(info)}。只扮演这个人物；不要声称已扣款或修改系统状态。图片尚未生成时可以提议提交占位。${M.stickerInstructions(offered)}`},...ms],token.controller.signal);if(taskValid(token)){const allowed=M.availableStickers(w).filter(s=>offered.some(old=>old.id===s.id));const reply=M.parseStickerReply(raw,allowed);C.message(w,id,role,reply.body,{...reply,from:client?'client':'artist'});await persist();}}
    catch(e){if(taskValid(token))toast(`私信失败，已保留发送内容：${e.message}`,true);}finally{if(running.get(key)===token){running.delete(key);if(epoch===token.epoch)render();}}
}
async function newModification(id){const {o,v}=C.findVersion(w,id);if(!['working','review'].includes(o.status))throw Error('已结束订单不能新建修改稿');const n={...structuredClone(v),id:C.uid(),number:o.versions.length+1,day:w.day,asset:null,accepted:false,status:v.positive?'prompted':'empty',source:'placeholder',error:null,parentId:v.id};o.versions.push(n);o.status='review';C.message(w,C.threadForOrder(o),o.owner,`新建${n.stage} V${n.number}，保留上一版提示词与种子供修改。`,{from:o.owner==='artist'?'user':'artist',orderId:o.id,versionId:n.id});await persist();}
