function paymentRegionModal(){const f=fundsAccount(),region=f?.region||w.settings.paymentRegion||'CN';modal('国家/地区',`<p>选择剧情中的付款地区，切换可用的虚拟支付方式。</p><label>国家/地区<select name="region">${Object.entries(F.regions).map(([key,r])=>`<option value="${key}" ${region===key?'selected':''}>${E(r.name)} · ${r.channels.join(' / ')}</option>`).join('')}</select></label>${field('bankName','自定义银行卡名称',f?.bankName||w.settings.bankName||'')}<label>补充世界书（仅首次读取时使用）<select name="financeBook"><option value="">跟随 user / 当前聊天关联世界书</option>${(A.context()?.getWorldInfoNames?.()||[]).map(name=>`<option value="${E(name)}" ${w.settings.financeBook===name?'selected':''}>${E(name)}</option>`).join('')}</select></label><p class="hy-muted">资金统一以剧情人民币等值记账，1 元对应 1 绘币。切换地区只替换账户显示名称，保留每个账户的余额和流水。</p>`,data=>{const region=data.get('region'),name=C.text(data.get('bankName'),50);if(f)F.setRegion(f,region,name);w.settings.paymentRegion=region;w.settings.bankName=name;w.settings.financeBook=C.text(data.get('financeBook'),500);});}
async function initializeFunds(){const identity=personaIdentity(),worldId=w.id,started=epoch;if(fundsAccount())throw Error('已经建立过账本，无需重新判断');modal('首次建立剧情资产',`<p>当前 user：<strong>${E(identity.name)}</strong></p><p>明确记载余额时直接使用；缺少余额时，需要将人设与相关世界书发送给酒馆当前文本模型判断。</p><p>只在这个世界首次建立该 user 的账本时读取。之后会把新增正文发送给酒馆当前文本模型提取收支，可随时暂停同步；刷新和编辑旧消息不会重复入账。</p>`,async()=>{const {result}=await initialEstimate(w);if(w.id!==worldId||epoch!==started||personaIdentity().key!==identity.key)throw Error('世界或 user 已切换，请重新打开');const c=A.context(),chatId=c?.getCurrentChatId?.()||'local';const f=F.initialize(w,identity,result,chatId,(c?.chat?.length||0)-1);f.bankName=w.settings.bankName||'';route={page:'funds'};toast('剧情资产已建立，将持续使用此账本');},'读取并建立账本');}
function rechargeModal(){const role=w.role,worldId=w.id,reference=C.uid(),identity=personaIdentity(),funds=fundsAccount();if(!funds){go('funds');return;}modal('充值绘币',`<div class="hy-recharge-hero"><span>HUIYUE WALLET</span><h3>给灵感，添一点底气。</h3><p>1 元 = 1 绘币</p>${tag('剧情账户转入')}</div><p>充值至 <strong>${E(profile().name)}</strong> 的${role==='artist'?'画师':'甲方'}钱包 · 当前 ${money(profile().balance)} 绘币</p><label>支付方式<select name="channel">${funds.channels.map(c=>`<option value="${c.id}">${E(F.channelName(funds,c))} · 余额 ¥${currency(c.cents)}</option>`).join('')}</select></label><div class="hy-recharge-options">${[30,100,300,1000].map(n=>`<label><input type="radio" name="preset" value="${n}" ${n===100?'checked':''}><span>¥${n}<small>${n} 绘币</small></span></label>`).join('')}</div>${field('amount','充值金额（元，整数）',100,'number','min="1" max="1000000" step="1" required')}<p class="hy-recharge-summary" aria-live="polite">到账 <strong>100 绘币</strong></p><p class="hy-muted">从选中的剧情支付账户扣除等额余额，转入当前身份的绘币钱包，并保留双方流水。不会产生真实付款。</p>`,data=>{if(w.id!==worldId||w.role!==role||personaIdentity().key!==identity.key)throw Error('身份或世界已切换，请重新打开充值页面');const amount=C.integer(data.get('amount'),1,1000000);F.recharge(w,identity.key,data.get('channel'),role,amount,reference);toast('已到账 '+money(amount)+' 绘币');},'确认充值');}
let fundsSyncChain=Promise.resolve();
function setFundsBaseline(){const c=A.context(),f=fundsAccount(),chatId=c?.getCurrentChatId?.()||'local';if(f&&!Object.hasOwn(f.cursors,chatId))f.cursors[chatId]=(c?.chat?.length||0)-1;}
function queueFundsSync(messageId,manual=false){
    const c=A.context(),f=fundsAccount(),identity=personaIdentity(),chatId=c?.getCurrentChatId?.()||'local',message=c?.chat?.[messageId];
    if(!f||!f.storySync){if(manual)throw Error('请先开启正文收支同步');return Promise.resolve();}
    if(!Number.isInteger(messageId)||!message||message.is_user||message.is_system)return Promise.resolve();
    const source={id:JSON.stringify([chatId,messageId]),chatId,messageId,body:String(message.mes||'')};
    if(!source.body.trim())return Promise.resolve();
    if(f.processed[source.id]){if(manual)toast('这条正文已经处理过，不会重复入账；编辑旧消息不会重新扣款');return Promise.resolve();}
    if(!manual&&messageId<=(f.cursors[chatId]??-1))return Promise.resolve();
    const target=w,started=epoch,region=f.region;
    const valid=()=>w===target&&epoch===started&&personaIdentity().key===identity.key&&(A.context()?.getCurrentChatId?.()||'local')===chatId&&f.storySync;
    const job=async()=>{if(!valid()||f.processed[source.id])return;
        try{
            const financial=/(支付|收款|收入|支出|到账|转账|付款|花了|花费|工资|奖金|报酬|余额|元|块|¥|￥|支付宝|微信|PayPal|Visa|银行卡)/i.test(source.body);
            const events=financial?await storyChanges(f,source):[];
            if(!valid())return;
            if(f.region!==region)throw Error('同步期间支付地区已改变，请在剧情资产中重试');
            const current=A.context()?.chat?.[messageId];
            if(String(current?.mes||'')!==source.body)throw Error('正文在同步期间被编辑，本次未入账，请核对后重试');
            const changed=F.applyStory(w,identity.key,source,events);f.cursors[chatId]=Math.max(f.cursors[chatId]??-1,messageId);if(f.pending)delete f.pending[source.id];if(!Object.keys(f.pending||{}).length)delete f.syncError;await persist();
            if(opened&&route.page==='funds')render();if(changed)toast('正文收支已记入剧情资产');else if(manual)toast('没有发现明确且可入账的收支');
        }catch(error){if(!valid())return;f.syncError='正文同步失败：'+error.message;(f.pending||={})[source.id]={chatId,messageId,error:error.message};await persist();if(opened&&route.page==='funds')render();toast(f.syncError,true);}
    };
    const pending=fundsSyncChain.catch(()=>{}).then(job);fundsSyncChain=pending;return pending;
}
function showLikePeople(id){const p=w.posts.find(p=>p.id===id);if(!p)throw Error('动态不存在');const people=C.likePeople(p),unknown=Math.max(0,p.likes-people.length);modal('这些人也喜欢',`<p>${p.likes} 个赞 · ${E(p.author)} 的动态</p>${people.map(person=>`<div class="hy-like-person"><span class="hy-person-badge">${E(person.name.slice(0,1))}</span><div><strong>${E(person.name)}</strong><small>${E(person.relation||'同好')}</small></div></div>`).join('')||empty('还没有记录到点赞昵称')}${unknown?`<p class="hy-muted">另有 ${unknown} 个旧版点赞未记录昵称。</p>`:''}`);}
