function uploadDMImage(id){const role=w.role,started=epoch;if(running.has(dmTaskKey(id)))throw Error('请等待当前回复完成后再发送图片');modal('发送图片',`<label>选择图片<input type="file" name="image" accept="image/png,image/jpeg,image/webp,image/gif,image/avif,image/bmp" required></label>${area('caption','图片说明（选填）','',3)}<p class="hy-muted">图片保存在私信和完整存档中。AI 会收到图片说明，原图不会自动交给文本模型识别；想讨论图片细节时，请补充文字描述。</p>`,async data=>{const file=data.get('image');if(!file?.size)throw Error('请选择图片');const asset=await putAssetSafe(file,file.name);if(epoch!==started||w.role!==role)throw Error('世界或身份已切换，请重新发送');C.message(w,id,role,C.text(data.get('caption'),4000),{from:'user',kind:'image',asset});scheduleMediaReply(id,role,started);},'发送图片');}
function stickerPicker(){modal('我的表情包',`<div class="hy-actions">${btn('addSticker','＋ 上传表情包')}${btn('toggleAIStickers',w.settings.aiStickersEnabled===false?'允许 AI 使用表情':'AI 可用：开')}</div><p class="hy-muted">给表情起个名字，AI 才能按语气选用。AI 最多选择最近 80 个表情中的一个；点击图片即可发送。</p><div class="hy-sticker-grid">${(w.stickers||[]).map(sticker=>`<article><button type="button" data-act="sendSticker" data-id="${E(sticker.id)}" aria-label="发送表情：${E(sticker.name)}">${img(sticker.asset,'hy-sticker-thumb')}<small>${E(sticker.name)}</small></button><div class="hy-actions">${btn('editSticker','编辑',sticker.id)}${btn('deleteSticker','删除',sticker.id)}</div></article>`).join('')||empty('上传第一个专属表情包吧')}</div>`);hydrate();}
function editSticker(id){const existing=w.stickers?.find(s=>s.id===id);modal(existing?'编辑表情包':'上传表情包',`${field('name','表情名称（例如：收到、猫猫疑惑）',existing?.name||'')}${area('description','含义 / 适合什么语气（选填）',existing?.description||'',2)}${existing?img(existing.asset,'hy-sticker-thumb'):'<label>表情图片<input type="file" name="image" accept="image/png,image/jpeg,image/webp,image/gif,image/avif,image/bmp" required></label>'}<p class="hy-muted">支持 GIF 动图，按原文件保存。表情会保存在当前绘约世界，并包含在完整存档中。</p>`,async data=>{const name=C.text(data.get('name'),50),description=C.text(data.get('description'),200);if(!name)throw Error('请填写表情名称');if(existing)Object.assign(existing,{name,description});else{const file=data.get('image');if(!file?.size)throw Error('请选择表情图片');const asset=await putAssetSafe(file,file.name);M.addSticker(w,{name,description,asset});}},'保存表情包');hydrate();}
const actions={
    orderAutomation:id=>{const o=getOrder(id);modal('本订单的自动生成设置',`<p class="hy-muted">可以单独覆盖全局开关；只对之后的占位和执行链生效。</p>${['autoPrompt','autoImage'].map((k,i)=>`<label>${i?'图片生成':'提示词生成'}<select name="${k}"><option value="inherit" ${typeof o.automation?.[k]!=='boolean'?'selected':''}>跟随全局设置</option><option value="on" ${o.automation?.[k]===true?'selected':''}>自动生成</option><option value="off" ${o.automation?.[k]===false?'selected':''}>手动触发</option></select></label>`).join('')}`,f=>{o.automation={};for(const k of ['autoPrompt','autoImage'])if(f.get(k)!=='inherit')o.automation[k]=f.get(k)==='on';});},
    close:closeApp,closeModal,
    nav:id=>go(id),back:()=>go(['artist','projects'].includes(route.page)?'home':['dm','order'].includes(route.page)?route.page==='dm'?'inbox':'bench':'me'),
    artist:id=>go('artist',id),dm:id=>{go('dm',id);setTimeout(()=>app.querySelector('#hy-dm-log')?.lastElementChild?.scrollIntoView({block:'end'}),30);},order:id=>go('order',id),bench:()=>go('bench'),settings:()=>go('settings'),projects:()=>go('projects'),
    filter:id=>{filter=id;render();},auctionFilter:id=>{filter=id;render();},feedFilter:id=>{feedFilter=id;render();},
    favorite:id=>{const a=w.artists.find(a=>a.id===id);a.favorite=!a.favorite;render();},editArtist:artistForm,
    aiArtist:()=>modal('AI 创建画师',area('idea','描述想要的画师','想要一位擅长梦幻水彩、慢热温柔的画师。'),async f=>{
        const raw=await completeSafe(w.settings.chat,'chat',[{role:'user',content:`创建一位全新的虚拟画师，不改写已有画师。只输出 JSON 对象：name,bio,personality,style,fans(整数),min(1-100000整数),max(>=min),days(1-365整数),revisions(0-30整数),refusal。需求：${C.text(f.get('idea'))}`}]);const p=A.parseJSON(raw);const a=C.artist({name:C.text(p.name,50)||'新画师',bio:C.text(p.bio,4000),personality:C.text(p.personality,2000),style:C.text(p.style,500),fans:C.integer(p.fans??0),min:C.integer(p.min??280,1),max:C.integer(p.max??1200,1),days:C.integer(p.days??12,1,365),revisions:C.integer(p.revisions??2,0,30),refusal:C.text(p.refusal,1000)});if(a.max<a.min)throw Error('AI 报价范围有误，请重试');w.artists.push(a);C.notify(w,`新画师 ${a.name} 加入绘约`);
    },'生成并添加'),
    quote:quoteForm,
    addWork:id=>modal('上传作品',`${field('title','作品标题','新的作品')}<label>原图<input type="file" accept="image/*" name="file" required></label>`,async f=>{const a=w.artists.find(a=>a.id===id),file=f.get('file');const asset=await putAssetSafe(file,file.name);a.works.push({id:C.uid(),title:C.text(f.get('title'),100),asset});}),
    removeWork:id=>confirmModal('移除作品','将从画师主页移除这张作品。订单版本与其他原文件不受影响。',()=>{for(const a of w.artists)a.works=a.works.filter(x=>x.id!==id);}),
    download:id=>S.downloadAsset(id),
    link:id=>confirmModal('关联当前角色',`将「${B.currentCharacter()?.name||'未打开角色'}」的身份资料关联到此画师，原角色卡不被修改。`,()=>B.linkCurrent(w.artists.find(a=>a.id===id))),
    unlink:id=>{w.artists.find(a=>a.id===id).linked=null;render();},
    pay:id=>confirmModal('确认订单并付款',`将 ${getOrder(id).price} 绘币转入虚拟托管。订单会按剧情天数推进，每阶段等待你验收。`,()=>{C.pay(w,id);}),
    acceptIncoming:id=>C.acceptIncoming(w,id),
    placeholder:id=>{const v=C.placeholder(w,id);persist().then(()=>afterPlaceholder(v)).catch(e=>toast(e.message,true));render();},
    makePlaceholder:id=>{const orders=w.commissions.filter(o=>o.owner===w.role&&C.threadForOrder(o)===id&&['working','review'].includes(o.status));if(!orders.length)throw Error('请先创建并确认一份委托订单');modal('选择稿件对应的订单',`<label>订单<select name="order">${orders.map(o=>`<option value="${E(o.id)}">${E(o.title)} · ${C.STAGES[o.stage]}</option>`).join('')}</select></label>`,f=>{const v=C.placeholder(w,f.get('order'));setTimeout(()=>afterPlaceholder(v),50);});},
    approve:id=>confirmModal('确认阶段验收',`确认「${getOrder(id).title}」的${C.STAGES[getOrder(id).stage]}阶段。文字稿也可以验收；图片生成需要另外操作。`,()=>C.approve(w,id)),
    revise:id=>modal('提出修改意见',area('note','请具体描述希望修改的细节'),f=>C.revise(w,id,f.get('note'))),
    cancelOrder:id=>confirmModal('协商取消委托','模拟双方已同意取消。已托管的甲方绘币会全额退回，稿件版本将保留。',()=>C.cancelOrder(w,id)),
    review:id=>modal('评价画师',`<label>星级<select name="stars">${[5,4,3,2,1].map(n=>`<option>${n}</option>`).join('')}</select></label>${area('body','合作感受')}`,f=>{const o=getOrder(id);if(o.status!=='complete'||o.reviewed)throw Error('订单尚未完成或已经评价');const a=w.artists.find(a=>a.id===o.artistId);a.reviews.push({stars:C.integer(f.get('stars'),1,5),body:C.text(f.get('body'),2000),day:w.day});o.reviewed=true;}),
    versionMain:id=>{const {v}=C.findVersion(w,id);if(running.has(id))return;if(v.asset)return actions.view(id);startTask(id,v.positive?'image':'prompt');},
    view:id=>{const {v}=C.findVersion(w,id);modal(`${v.stage} V${v.number}`,`${v.asset?img(v.asset,'hy-full-image'):empty('图片尚未添加')}${v.asset?btn('download','↓ 下载原文件',v.asset):''}<p>${E(v.note)}</p><details><summary>生成参数与提示词</summary><pre>${E(JSON.stringify({positive:v.positive,negative:v.negative,seed:v.seed,params:v.params,artistPreset:v.artistPresetSnapshot},null,2))}</pre></details>`);hydrate();},
    cancelTask:id=>{const t=running.get(id);if(t){t.controller.abort();running.delete(id);}const {v}=C.findVersion(w,id);v.status=v.asset?'ready':v.positive?'prompted':'empty';v.error=null;toast('已放弃本次返回结果。酒馆或远端 API 可能仍在执行和计费。');render();},
    uploadVersion:async id=>{const {o,v}=C.findVersion(w,id);const capturedEpoch=epoch,asset=await upload();if(!asset||capturedEpoch!==epoch)return;running.get(id)?.controller.abort();running.delete(id);if(v.asset){const n={...structuredClone(v),id:C.uid(),parentId:v.id,number:o.versions.length+1,asset,source:'upload',status:'ready',accepted:false,error:null,day:w.day};o.versions.push(n);C.message(w,C.threadForOrder(o),o.owner,`上传了一份新的 ${n.stage} V${n.number}，旧版本已经保留。`,{from:o.owner==='artist'?'user':'artist',orderId:o.id,versionId:n.id});}else{v.asset=asset;v.status='ready';v.source='upload';v.error=null;}render();},
    newVersion:newModification,
    editPrompt:id=>{const {o,v}=C.findVersion(w,id);const promptEpoch=epoch,defaults=C.artistPresets(w.artists.find(a=>a.id===o.artistId));if(running.has(id))throw Error('请先放弃正在生成的结果');modal('编辑本版提示词',`${area('positive','正向提示词',v.positive||defaults.positive,6)}${area('negative','负向提示词',v.negative||(!v.positive?defaults.negative:''),3)}${field('seed','种子（保留以供复现）',v.seed,'number')}<p class="hy-muted">${v.asset?'此版本已有原图，修改提示词需要创建新版本。':'保存后点击「生成图片」执行下一步。'}</p>`,async f=>{let target=v;if(v.asset||v.accepted){await newModification(id);target=C.findVersion(w,id).o.versions.at(-1);}target.positive=C.text(f.get('positive'));target.negative=C.text(f.get('negative'));target.seed=C.integer(f.get('seed'),0,2147483647);target.status=target.positive?'prompted':'empty';target.error=null;if(target.positive&&automation(o,'autoImage'))setTimeout(()=>{if(promptEpoch===epoch)try{startTask(target.id,'image');}catch(e){toast(e.message,true);}},80);});},
    editNote:id=>{const {v}=C.findVersion(w,id);modal('文字稿件说明',area('note','构图、配色、阶段成果或修改说明',v.note,6),f=>{v.note=C.text(f.get('note'));});},
    advance:()=>modal('推进剧情时间',`<p>目前是剧情日 ${w.day}。只有主动推进才会改变工期和拍卖日期。</p><label>推进天数<select name="days"><option value="1">1 天</option><option value="3">3 天</option><option value="7">1 周</option></select></label><p class="hy-muted">待验收的稿件会暂停推进，不会跳过阶段。随机事件可在设置中关闭。</p>`,f=>{const vs=C.advance(w,f.get('days'));setTimeout(()=>{if(vs.length)autoQueue(vs.map(v=>v.id));},100);},'推进'),
    createAuction:()=>modal('发布稿拍',`${field('title','拍品名称')}<label>类型<select name="type"><option>成稿</option><option>OC 人设</option><option>画师档期</option></select></label>${area('description','介绍、授权与档期说明')}${field('start','起拍价',100,'number')}${field('increment','最小加价',20,'number')}${field('duration','持续剧情天数',3,'number')}<label>拍品图片（档期类型可不传）<input type="file" name="file" accept="image/*"></label>`,async f=>{let asset=null;const file=f.get('file');if(file?.size)asset=await putAssetSafe(file,file.name);C.auction(w,{...Object.fromEntries(f),asset,seller:w.role});}),
    bid:id=>{const a=w.auctions.find(x=>x.id===id),min=a.bids.at(-1)?a.bids.at(-1).amount+a.increment:a.start;modal('参与虚拟竞拍',`<p>出价后会预留绘币，被超价时立即退回。剧情日 ${a.endDay} 结束时自动结算。</p>${field('amount','你的出价',min,'number')}`,f=>C.bid(w,id,f.get('amount'),w.role),'确认出价');},
    claimSlot:id=>{const a=w.auctions.find(a=>a.id===id);if(a.winner!==w.role||a.type!=='画师档期')throw Error('没有这个档期的使用权');modal('使用成交档期',`<p>档期所有权已经保存。请指定关联画师后发起委托，画费另行协商；成交金额视为购买档期费用。</p><label>画师<select name="artistId">${w.artists.map(a=>`<option value="${E(a.id)}">${E(a.name)}</option>`).join('')}</select></label>`,f=>{a.artistId=f.get('artistId');const ar=w.artists.find(x=>x.id===a.artistId);ar.available=w.day;ar.open=true;route={page:'artist',id:ar.id};});},
    createPost:()=>modal('发布一条动态',`<label>分类<select name="category"><option>稿件</option><option>生活</option><option>灵感</option><option>公告</option></select></label>${area('body','想分享什么？')}<label>图片<input type="file" name="file" accept="image/*"></label>`,async f=>{const body=C.text(f.get('body'));if(!body)throw Error('请填写动态正文');let asset=null;const file=f.get('file');if(file?.size)asset=await putAssetSafe(file,file.name);w.posts.unshift(C.socialReactions(w,{id:C.uid(),author:profile().name,avatar:profile().avatar,role:w.role,body,category:f.get('category'),asset,day:w.day,likes:0,liked:false,comments:[]}));}),
    like:id=>{C.toggleLike(w,w.posts.find(p=>p.id===id));render();},
    comment:id=>modal('写一条评论',area('body','评论'),f=>{const body=C.text(f.get('body'),2000);if(!body)throw Error('评论不能为空');w.posts.find(p=>p.id===id).comments.push({author:profile().name,body,day:w.day});}),
    npcPost:()=>{const a=w.artists[Math.floor(Math.random()*w.artists.length)];if(!a)throw Error('请先添加画师');w.posts.unshift(C.socialReactions(w,{id:C.uid(),author:a.name,artistId:a.id,category:'生活',body:'整理了最近的创作笔记，想试试新的配色。也欢迎来聊聊你们的 OC！',day:w.day,asset:null,likes:0,liked:false,comments:[]}));render();},
    aiPost:()=>modal('AI 画师动态',`<label>选择画师<select name="artist">${w.artists.map(a=>`<option value="${E(a.id)}">${E(a.name)}</option>`).join('')}</select></label>${field('idea','动态主题','最近的创作或生活小事')}`,async f=>{const a=w.artists.find(a=>a.id===f.get('artist'));const body=await completeSafe(w.settings.chat,'chat',[{role:'user',content:`扮演虚拟画师 ${a.name}。人设：${a.linked?.personality||a.personality}。画风：${a.style}。剧情日 ${w.day}，写一条不超过 200 字的朋友圈动态，主题：${C.text(f.get('idea'))}。只返回正文，不声称改变订单或已提交图片。`}]);w.posts.unshift(C.socialReactions(w,{id:C.uid(),author:a.name,artistId:a.id,category:'生活',body:C.text(body,3000),day:w.day,asset:null,likes:0,liked:false,comments:[]}));},'生成并发布'),
    switchRole:()=>{if(w.role==='client'&&!w.artistActivated){modal('你好，画师小伙伴！',`<div class="hy-welcome-art">${mascot(true)}</div><div class="hy-welcome-copy"><span class="hy-eyebrow">A LITTLE STUDIO, A NEW STORY</span><h3>小绘来为你剪彩啦！</h3><p>开通画师身份，拥有独立的主页、钱包与收件箱，接收虚拟客户的约稿。</p><p class="hy-muted">已保存的画师资料和余额会继续保留。你随时可以在「我的」中注销，停止接收新请求。</p></div>`,()=>{C.activateArtist(w);},'开通我的画室');}else{w.role=w.role==='client'?'artist':'client';render();}},
    deactivateArtist:()=>confirmModal('暂时收起画室？','注销后回到甲方身份，不再接收新约稿；未接的请求将关闭，已接订单、稿件、资料和绘币保留。再次开通时会重新确认。',()=>{C.deactivateArtist(w);go('me');}),
    uploadDMImage,stickerPicker,addSticker:()=>editSticker(),editSticker,
    toggleAIStickers:()=>{w.settings.aiStickersEnabled=w.settings.aiStickersEnabled===false;stickerPicker();},
    sendSticker:id=>{const sticker=w.stickers?.find(s=>s.id===id);if(!sticker)throw Error('表情不存在');if(route.page!=='dm')throw Error('请先打开私信');if(running.has(dmTaskKey(route.id)))throw Error('请等待当前回复完成');const role=w.role,started=epoch,target=route.id;C.message(w,target,role,'',{from:'user',kind:'sticker',asset:sticker.asset,stickerId:id,stickerName:sticker.name});closeModal();scheduleMediaReply(target,role,started);},
    deleteSticker:id=>confirmModal('删除这个表情？','表情将从可选列表移除，已发送的聊天图片仍会保留。',()=>{w.stickers=(w.stickers||[]).filter(s=>s.id!==id);}),
    viewDMImage:asset=>{modal('聊天图片',img(asset,'hy-full-image')+btn('download','下载原图',asset));hydrate();},
    resetLauncherPosition:()=>{floating.resetPosition();toast('已恢复默认悬浮位置');},
    recharge:rechargeModal,launcherSettings,likePeople:showLikePeople,funds:()=>go('funds'),paymentRegion:paymentRegionModal,initializeFunds,
    toggleStorySync:()=>{const f=fundsAccount();f.storySync=!f.storySync;const c=A.context(),chatId=c?.getCurrentChatId?.()||'local';f.cursors[chatId]=(c?.chat?.length||0)-1;toast(f.storySync?'已开启，只同步之后的新正文':'正文收支同步已暂停');},
    retryFunds:async id=>{const entry=fundsAccount()?.pending?.[id];if(!entry)throw Error('记录不存在');if((A.context()?.getCurrentChatId?.()||'local')!==entry.chatId)throw Error('请切回这条正文所在的酒馆聊天后重试');await queueFundsSync(entry.messageId,true);},
    syncFunds:async()=>{const c=A.context();let id=(c?.chat?.length||0)-1;while(id>=0&&(c.chat[id].is_user||c.chat[id].is_system))id--;if(id<0)throw Error('当前聊天没有可同步的正文');await queueFundsSync(id,true);},
    incoming:()=>{C.incoming(w);go('bench');},
    editAccount:()=>{const p=profile();modal('编辑身份资料',`${field('name','昵称',p.name)}${area('bio','简介',p.bio)}<label>头像<input type="file" name="file" accept="image/*"></label>${w.role==='artist'?field('min','最低报价',p.min,'number')+field('max','最高报价',p.max,'number')+field('days','工期（剧情日）',p.days,'number')+field('revisions','修改次数',p.revisions,'number')+area('promptPreset','画师串 / 风格预设（正向）',p.promptPreset||'',3)+area('negativePreset','默认负向提示词',p.negativePreset||'',2):''}`,async f=>{const name=C.text(f.get('name'),50);if(!name)throw Error('昵称不能为空');const update={name,bio:C.text(f.get('bio'),4000)};const file=f.get('file');if(file?.size)update.avatar=await putAssetSafe(file,file.name);if(w.role==='artist'){update.min=C.integer(f.get('min'),1);update.max=C.integer(f.get('max'),update.min);update.days=C.integer(f.get('days'),1,365);update.revisions=C.integer(f.get('revisions'),0,30);update.promptPreset=C.text(f.get('promptPreset'),4000);update.negativePreset=C.text(f.get('negativePreset'),4000);}Object.assign(p,update);if(w.settings.sharedProfile)Object.assign(w.accounts[w.role==='client'?'artist':'client'],{name:p.name,bio:p.bio,avatar:p.avatar});});},
    wallet:()=>modal('虚拟钱包账本',`<p>当前余额 ${money(profile().balance)} 绘币。初始赠送仅用于模拟。</p>${w.ledger.filter(l=>l.role===w.role).slice().reverse().map(l=>`<div class="hy-ledger"><span>${E(l.reason)}<small>第 ${l.day} 日</small></span><strong>${l.delta>0?'+':''}${l.delta}</strong><small>余额 ${l.balance}</small></div>`).join('')||empty('还没有交易记录')}`),
    retryDM:id=>aiReply(id),manualReply:id=>modal('手动扮演对方',area('body','对方的回复'),f=>{C.message(w,id,w.role,f.get('body'),{from:C.isCustomer(w,id)?'client':'artist'});}),
    accountStyle:styleModal,bridge:bridgeModal,
    applyBridge:id=>{const e=w.bridge.find(e=>e.id===id),os=w.commissions.filter(o=>o.artistId===e.artistId&&o.status==='working');if(!os.length)throw Error('没有对应的绘制中订单，请先创建订单');modal('确认聊天同步事件',`<p>${E(e.body)}</p><label>对应订单<select name="order">${os.map(o=>`<option value="${E(o.id)}">${E(o.title)}</option>`).join('')}</select></label><p class="hy-muted">确认后仅建立稿件占位，不自动调用 API。</p>`,f=>B.applyCandidate(w,id,f.get('order')));},
    dismissBridge:id=>{w.bridge.find(e=>e.id===id).status='dismissed';bridgeModal();},undoBridge:id=>{B.undoCandidate(w,id);bridgeModal();},
    npc:()=>modal('提取角色卡与世界书 NPC','<p>将读取当前角色卡及其关联世界书的文字，交给所选私信 AI 提取人物。返回候选后由你勾选，已有画师不会自动覆盖。</p>',async()=>{const candidates=await B.npcCandidates(w);setTimeout(()=>modal('确认要添加的 NPC',candidates.map((a,i)=>check('npc'+i,`${a.name} · ${a.personality.slice(0,100)}`,false)).join('')||'<p>没有提取到人物。</p>',f=>{candidates.forEach((a,i)=>{if(f.has('npc'+i))w.artists.push(C.artist(a));});}),30);},'读取并提取'),
    bindChat:async()=>{const c=A.context();if(!c?.getCurrentChatId?.())throw Error('请先打开并保存一个酒馆聊天');await persist();if(!c.chatMetadata.huiyue)c.chatMetadata.huiyue={worldId:C.uid()};await c.saveMetadata();await switchWorld(c.chatMetadata.huiyue.worldId);toast('已打开当前聊天专属世界；原独立世界仍保留');},
    globalWorld:()=>switchWorld(globalId),
    export:()=>S.exportWorld(w),
    exportOrder:async id=>{const o=getOrder(id),copy=C.newWorld();copy.commissions=[structuredClone(o)];copy.artists=structuredClone(w.artists.filter(a=>a.id===o.artistId));copy.day=w.day;copy.accounts=structuredClone(w.accounts);copy.customers=structuredClone((w.customers||[]).filter(c=>c.id===o.clientId));copy.messages={};await S.exportWorld(copy);toast('订单包已导出，可独立恢复浏览；不会自动合并进其他世界');},
    import:()=>confirmModal('恢复完整存档','将用所选存档替换当前世界。建议先导出当前世界留作备份；其他聊天世界不会改变。',async()=>{const target=w.id,started=epoch;const f=await pickFile('application/json,.json');if(!f||started!==epoch)return;await saveChain;const restored=await S.importWorld(f,target);if(started!==epoch)return;abortAll();epoch++;w=restored;C.migrateCustomerThreads(w);route={page:'home'};toast('存档和图片已恢复');}),
    reset:()=>confirmModal('重置当前世界','将清空当前世界的订单、画师和平台活动并重新开始。请先导出存档保留原图和资料。其他世界不受影响。',()=>{abortAll();epoch++;w=C.newWorld(w.id);route={page:'home'};}),
    createProject:()=>modal('发布企划',`${field('title','企划标题')}${area('brief','角色设定与画面需求')}${field('budget','预算（绘币）',800,'number')}${field('deadline','截稿剧情日',w.day+14,'number')}`,f=>{if(!C.text(f.get('title'))||!C.text(f.get('brief')))throw Error('请填写标题与需求');w.projects.unshift({id:C.uid(),title:C.text(f.get('title'),100),brief:C.text(f.get('brief')),budget:C.integer(f.get('budget'),1),deadline:C.integer(f.get('deadline'),w.day+1),applicants:[]});}),
    simulateApplicants:id=>{const p=w.projects.find(p=>p.id===id);if(p.deadline<=w.day)throw Error('企划已经截稿');p.applicants=w.artists.filter(a=>a.open&&a.available<=w.day&&a.min<=p.budget).map(a=>a.id);C.notify(w,`企划「${p.title}」收到 ${p.applicants.length} 份应征`);render();},
    applicants:id=>{const p=w.projects.find(p=>p.id===id);modal('企划画师与应征',`${w.artists.map(a=>`<div class="hy-ledger"><span>${E(a.name)} ${p.applicants.includes(a.id)?tag('已应征'):''}</span>${btn('inviteProject','邀请约稿',p.id+':'+a.id)}</div>`).join('')}`);},
    inviteProject:id=>{const [pid,aid]=id.split(':');const p=w.projects.find(p=>p.id===pid);quoteForm(aid,p);}
};
async function autoQueue(ids){const started=epoch;for(const id of ids){if(started!==epoch)break;while(started===epoch&&[...running.values()].some(t=>t.kind!=='dm'))await new Promise(r=>setTimeout(r,300));if(started!==epoch)break;try{const {o}=C.findVersion(w,id);if(automation(o,'autoPrompt'))startTask(id,'prompt');}catch(e){toast(e.message,true);}}}
function abortAll(){for(const t of running.values())t.controller.abort();running.clear();}
async function switchWorld(id){closeModal();abortAll();epoch++;const loadEpoch=epoch;if(w)await saveChain.catch(()=>{});const loaded=await S.loadWorld(id)||C.newWorld(id);if(loadEpoch!==epoch)return;w=loaded;C.migrateCustomerThreads(w);setFundsBaseline();for(const o of w.commissions)for(const v of o.versions)if(['prompting','drawing'].includes(v.status))v.status=v.asset?'ready':v.positive?'prompted':'empty';route={page:'home'};await persist();render();}
async function handleAction(e){const b=e.target.closest('[data-act]');if(!b)return;e.preventDefault();const act=b.dataset.act;if(act==='like'&&suppressLike===b.dataset.id){e.preventDefault();return;}if(act==='retryOpen'){await openApp();return;}if(!actions[act])return;try{await actions[act](b.dataset.id);if(w)await persist();if(!app.querySelector('.hy-modal'))render();}catch(err){toast(err.message,true);}}
let holdTimer,holdStart,suppressLike='';
function stopHold(){clearTimeout(holdTimer);holdTimer=null;holdStart=null;}
app.addEventListener('pointerdown',e=>{const button=e.target.closest('[data-act="like"]');if(!button||e.button!==0)return;stopHold();holdStart={x:e.clientX,y:e.clientY};holdTimer=setTimeout(()=>{const id=button.dataset.id;suppressLike=id;stopHold();showLikePeople(id);setTimeout(()=>suppressLike='',800);},550);});
app.addEventListener('pointermove',e=>{if(holdStart&&Math.hypot(e.clientX-holdStart.x,e.clientY-holdStart.y)>10)stopHold();});
app.addEventListener('pointerup',stopHold);app.addEventListener('pointercancel',stopHold);
app.addEventListener('contextmenu',e=>{const button=e.target.closest('[data-act="like"]');if(button){e.preventDefault();stopHold();suppressLike=button.dataset.id;showLikePeople(button.dataset.id);setTimeout(()=>suppressLike='',800);}});
app.addEventListener('change',e=>{if(e.target.name==='preset'){const form=e.target.form;form.elements.amount.value=e.target.value;form.elements.amount.dispatchEvent(new Event('input',{bubbles:true}));}});
app.addEventListener('input',e=>{if(e.target.name==='amount'){const form=e.target.form,n=Number(e.target.value),summary=form?.querySelector('.hy-recharge-summary');if(summary)summary.textContent=Number.isSafeInteger(n)&&n>=1&&n<=1000000?'到账 '+money(n)+' 绘币':'请输入 1–1,000,000 之间的整数';}if(e.target.name==='size'){const out=e.target.form?.querySelector('.hy-size-output');if(out)out.textContent=e.target.value+' px';}});
app.addEventListener('click',e=>{if(e.target.closest('[data-reset-dm-preset]')){const input=app.querySelector('[name=dmPreset]');if(input)input.value=DEFAULT_DM_PRESET;toast('已填入默认预设，点击保存设置后生效');}});
bindModelPickers(app,A);
app.addEventListener('click',handleAction);
app.addEventListener('submit',async e=>{const f=e.target;if(!f.dataset.form)return;e.preventDefault();const data=new FormData(f);try{switch(f.dataset.form){case 'search':search=C.text(data.get('q'),100);render();break;
    case 'dm':{const body=C.text(data.get('body'));if(!body)return;const id=route.id;C.message(w,id,w.role,body,{from:'user'});await persist();render();aiReply(id);break;}
    case 'settings':{if(f.querySelector('[data-connecting]'))throw Error('请等待模型列表读取完成后再保存');const next=structuredClone(w.settings);next.dmPreset=C.text(data.get('dmPreset'),10000);for(const k of ['autoPrompt','autoImage','randomEvents','sharedProfile'])next[k]=data.has(k);for(const kind of ['chat','prompt','image']){for(const k of ['mode','url','model','apiAuth','modelsPath','requestPath','extraParams',...(kind==='image'?['imageProtocol','imageResponse','imageSizeMode','imageModalities','naiSampler','naiNoise']:['textProtocol','template']),...(['prompt','image'].includes(kind)?['instructions']:[])])next[kind][k]=C.text(data.get(`${kind}.${k}`),['template','instructions','extraParams'].includes(k)?10000:1000);if(next[kind].mode==='openai'){if(!next[kind].model)throw Error('请先拉取并选择模型');A.validateRelay(next[kind],kind);}}
        next.image.width=C.integer(data.get('width'),256,4096);next.image.height=C.integer(data.get('height'),256,4096);next.image.steps=C.integer(data.get('steps'),1,150);const cfg=Number(data.get('cfg'));if(!Number.isFinite(cfg)||cfg<0||cfg>40)throw Error('CFG 请输入 0–40');next.image.cfg=cfg;for(const kind of ['chat','prompt','image']){const key=data.get(`${kind}.key`);if(key)A.setKey(kind,key);}w.settings=next;await persist();toast('设置已保存；密钥仅保留在当前页面内存中');render();break;}
}}catch(err){toast(err.message,true);}});
function closeApp(){if(typeof app.close==='function'&&app.open)app.close();app.hidden=true;opened=false;updateLauncher();}
function showApp(){
    app.hidden=false;launcher.hidden=true;opened=true;updateLauncher();
    if(typeof app.showModal==='function'&&!app.open)app.showModal();
    const toastElement=document.getElementById('hy-toast');if(toastElement)app.append(toastElement);
}
async function openApp(){
    try{
        showApp();
        if(!w)app.innerHTML='<main class="hy-main"><h1>✿ 绘约</h1><p role="status">正在读取本地存档…</p>'+btn('close','关闭')+'</main>';
        await S.openDB();
        if(!w)await switchWorld(A.context()?.chatMetadata?.huiyue?.worldId||globalId);
        if(opened)render();
    }catch(e){
        console.error('[绘约] 打开失败',e);
        if(!opened)return;
        const message=String(e?.message||e);
        app.innerHTML='<header class="hy-header"><strong>✿ 绘约 · 打开失败</strong>'+btn('close','×','','hy-icon')+'</header><main class="hy-main"><h1>暂时无法打开绘约</h1><p class="hy-error">'+E(message)+'</p><p>请截图保留这条错误信息。无需清除浏览器数据或重置存档。</p><pre>'+E(JSON.stringify({version:'1.3.1',protocol:location.protocol,secureContext:globalThis.isSecureContext,randomUUID:typeof globalThis.crypto?.randomUUID,indexedDB:(()=>{try{return typeof globalThis.indexedDB;}catch{return 'blocked';}})()},null,2))+'</pre><div class="hy-actions">'+btn('retryOpen','重试打开','','hy-primary')+btn('close','返回酒馆')+'</div></main>';
    }
}
launcher.addEventListener('click',openApp);
updateLauncher();
// Delegation survives host panels recreating their settings markup.
document.addEventListener('click',e=>{if(e.target.closest?.('[data-huiyue-open]')){e.preventDefault();openApp();}},true);
app.addEventListener('cancel',e=>{e.preventDefault();closeApp();});
app.addEventListener('close',()=>{if(!app.open&&opened)closeApp();});
function renderChatCards(){document.querySelectorAll('.hy-st-card').forEach(e=>e.remove());const c=A.context();if(!w?.settings.bridgeEnabled||!c)return;const chatId=c.getCurrentChatId?.()||'';for(const log of w.bridge.filter(x=>x.status==='applied'&&x.chatId===chatId)){const el=document.querySelector(`.mes[mesid="${Number(log.messageId)}"] .mes_text`);if(el){const card=document.createElement('button');card.className='hy-st-card';card.type='button';card.textContent='✿ 绘约 · 打开已同步的稿件';card.addEventListener('click',()=>{showApp();go('order',log.orderId);});el.insertAdjacentElement('afterend',card);}}}
function hookTavern(){const c=A.context();if(!c)return;const types=c.eventTypes||c.event_types;
    c.eventSource?.on(types.CHAT_CHANGED,async()=>{try{const id=A.context()?.chatMetadata?.huiyue?.worldId||globalId;await switchWorld(id);}catch(e){toast(e.message,true);}});
    c.eventSource?.on(types.MESSAGE_RECEIVED,async id=>{if(!w)return;queueFundsSync(Number(id));if(B.detectChatEvent(w,id)){await persist();if(opened&&['me','inbox'].includes(route.page))render();toast('绘约发现交稿话语，请在「我的 → 剧情同步」确认');}});
    if(types.CHARACTER_MESSAGE_RENDERED)c.eventSource?.on(types.CHARACTER_MESSAGE_RENDERED,id=>{if(w)queueFundsSync(Number(id));});
    if(types.PERSONA_CHANGED)c.eventSource?.on(types.PERSONA_CHANGED,async()=>{if(!w)return;setFundsBaseline();await persist();if(opened)render();});
    for(const type of [types.MESSAGE_UPDATED,types.CHARACTER_MESSAGE_RENDERED,types.MORE_MESSAGES_LOADED].filter(Boolean))c.eventSource?.on(type,()=>renderChatCards());
    if(c.SlashCommandParser&&c.SlashCommand){c.SlashCommandParser.addCommandObject(c.SlashCommand.fromProps({name:'huiyue',callback:async()=>{await openApp();return '';},helpString:'打开绘约虚拟约稿平台。'}));}
    const mount=document.querySelector('#extensions_settings2')||document.querySelector('#extensions_settings');if(mount){const panel=document.createElement('div');panel.className='extension_container';const b=document.createElement('button');b.textContent='✿ 打开绘约 · v1.3.1';b.className='menu_button';b.type='button';b.dataset.huiyueOpen="true";panel.append(b);mount.append(panel);}
}
function installWandEntry(){const menu=document.getElementById('extensionsMenu');if(!menu||menu.querySelector('[data-huiyue-open]'))return;const item=document.createElement('div');item.id='huiyue_wand_entry';item.className='list-group-item flex-container flexGap5';item.setAttribute('role','button');item.tabIndex=0;item.dataset.huiyueOpen='true';item.innerHTML='<span class="hy-wand-symbol">'+launcherIcon+'</span><span>绘约 · 约稿平台</span>';item.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openApp();}});menu.append(item);const button=document.getElementById('extensionsMenuButton');if(button)button.style.display='flex';}
installWandEntry();const entryObserver=new MutationObserver(()=>installWandEntry());entryObserver.observe(document.body,{childList:true,subtree:true});
globalThis.Huiyue={version:'1.3.1',open:openApp,registerImageAdapter:A.registerImageAdapter};
hookTavern();
if(!A.context())openApp();
else switchWorld(A.context()?.chatMetadata?.huiyue?.worldId||globalId).catch(e=>toast(e.message,true));
window.addEventListener('beforeunload',()=>{for(const u of urls.values())URL.revokeObjectURL(u);});
